package com.productionhouse.crm.audio.singer.service;
import com.productionhouse.crm.auth.api.ApiException;import com.productionhouse.crm.audio.singer.dto.*;import com.productionhouse.crm.audio.singer.entity.SingerProfile;import com.productionhouse.crm.audio.singer.repository.SingerProfileRepository;import com.productionhouse.crm.task5.util.Task5Paging;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class SingerProfileService{
private final SingerProfileRepository repo;public SingerProfileService(SingerProfileRepository repo){this.repo=repo;}
@Transactional(readOnly=true) public Page<SingerResponse> list(String q,String language,String status,Boolean active,int page,int size,String sort,String direction){String field=Set.of("name","status","createdAt","updatedAt").contains(sort)?sort:"createdAt";Sort order=Sort.by("asc".equalsIgnoreCase(direction)?Sort.Direction.ASC:Sort.Direction.DESC,field);return Task5Paging.page(repo.findAll(order).stream().filter(e->blank(q)||contains(e.getName(),q)).filter(e->blank(language)||csvContains(e.getLanguages(),language)).filter(e->blank(status)||status.equalsIgnoreCase(e.getStatus())).filter(e->active==null||active==e.isActive()).map(this::response).toList(),page,size);}
@Transactional(readOnly=true) public SingerResponse get(Long id){return response(find(id));}
@Transactional public SingerResponse create(SingerRequest r){return response(save(new SingerProfile(),r));}
@Transactional public SingerResponse update(Long id,SingerRequest r){return response(save(find(id),r));}
@Transactional public void delete(Long id){repo.delete(find(id));}
private SingerProfile find(Long id){return repo.findById(id).orElseThrow(()->ApiException.notFound("Singer not found."));}
private SingerProfile save(SingerProfile e,SingerRequest r){String status=r.status().trim().toUpperCase(Locale.ROOT);if(!Set.of("ACTIVE","INACTIVE").contains(status))throw ApiException.badRequest("Singer status must be ACTIVE or INACTIVE.");if(r.active()!=null&&r.active()!=status.equals("ACTIVE"))throw ApiException.badRequest("active must agree with status.");e.setName(r.name().trim());e.setDescription(clean(r.biography()));e.setEmail(clean(r.email()));e.setPhone(clean(r.phone()));e.setLanguages(clean(r.languages()));e.setVoiceType(clean(r.voiceType()));e.setVoiceRange(clean(r.voiceRange()));e.setStatus(status);e.setActive(r.active()==null?status.equals("ACTIVE"):r.active());return repo.save(e);}
private SingerResponse response(SingerProfile e){return new SingerResponse(e.getId(),e.getName(),e.getEmail(),e.getPhone(),e.getLanguages(),e.getVoiceType(),e.getVoiceRange(),e.getDescription(),e.getStatus(),e.isActive(),e.getCreatedAt(),e.getUpdatedAt());}
private boolean blank(String x){return x==null||x.isBlank();}private boolean contains(String x,String q){return x!=null&&x.toLowerCase(Locale.ROOT).contains(q.trim().toLowerCase(Locale.ROOT));}private boolean csvContains(String csv,String q){return csv!=null&&Arrays.stream(csv.split(",")).anyMatch(x->x.trim().equalsIgnoreCase(q.trim()));}private String clean(String x){return x==null||x.isBlank()?null:x.trim();}}

